440	    /* mở file trong trang: kích thước, số màu khác nhau trong 400 điểm mẫu, có phải toàn đen không */
441	    const analyse = async (d) => {
442	      const buf = readFileSync(await d.path());
443	      const r = await Q.evaluate(async (b64) => {
444	        const bin = atob(b64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
445	        const bmp = await createImageBitmap(new Blob([u], { type: 'image/png' }));
446	        const c = document.createElement('canvas'); c.width = bmp.width; c.height = bmp.height;
447	        const g = c.getContext('2d'); g.drawImage(bmp, 0, 0);
448	        const cols = new Set(); let lit = 0;
449	        for (let iy = 0; iy < 20; iy++) for (let ix = 0; ix < 20; ix++) {
450	          const px = g.getImageData(Math.min(bmp.width - 1, Math.floor((ix + 0.5) * bmp.width / 20)), Math.min(bmp.height - 1, Math.floor((iy + 0.5) * bmp.height / 20)), 1, 1).data;
451	          cols.add(px[0] + ',' + px[1] + ',' + px[2]); if (px[0] + px[1] + px[2] > 12) lit++;
452	        }
453	        return { w: bmp.width, h: bmp.height, colors: cols.size, lit };
454	      }, buf.toString('base64'));
455	      return { name: d.suggestedFilename(), ...r };
456	    };
457	    const waitCount = async (n) => { const t0 = Date.now(); while (got.length < n && Date.now() - t0 < 240000) await Q.waitForTimeout(200); };
458	    const valid = (a) => NAME.test(a.name) && a.colors >= 20 && a.lit > 0;
459	    const cv = () => Q.evaluate(() => { const c = document.querySelector('canvas'); return { w: c.width, h: c.height }; });
460	    // bấm #stPhoto: đúng 1 file
461	    await Q.click('#stPhoto');
462	    await waitCount(1);
463	    const toast = await Q.evaluate(() => { const e = document.getElementById('exMpNotice'); return { hidden: e.hidden, text: e.textContent }; });   // đọc ngay: thông báo tự ẩn sau noticeMs (8 s), SwiftShader chậm
464	    await frames(Q, 4);
465	    const a1 = await analyse(got[0]), c1 = await cv();
466	    check(`11 bấm #stPhoto: ${got.length} file (= 1) "${a1.name}", ${a1.w}×${a1.h} = canvas ${c1.w}×${c1.h}, ${a1.colors} màu / 400 điểm, sáng ${a1.lit}`, got.length === 1 && valid(a1) && a1.w === c1.w && a1.h === c1.h);
467	    const last = await Q.evaluate(() => window.__app.stroll.stroll.photoLast);
468	    check(`11 thông báo "${toast.text}" (stPhotoSaved)`, !toast.hidden && toast.text === 'Đã lưu ảnh');
469	    check(`11 photoLast ${JSON.stringify(last)} khớp file`, !!last && last.name === a1.name && last.w === a1.w && last.h === a1.h && last.size > 1000);
470	    // phím p: thêm đúng 1 file; pose 4 khi đứng yên rồi về 0
471	    await Q.evaluate(() => document.activeElement && document.activeElement.blur());
472	    await Q.keyboard.press('p');
473	    const pose = await Q.evaluate(() => {
474	      const S = window.__app.stroll.stroll, idle = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 }, hold = window.__app.stroll.CONFIG_stroll.photoHold;
475	      S.step(0.016, idle); const p0 = S.state.pose;
476	      let t = 0, p1 = p0; while (t < hold - 0.1) { S.step(0.05, idle); t += 0.05; p1 = S.state.pose; }
477	      for (let i = 0; i < 6; i++) S.step(0.05, idle);
478	      return { p0, p1, end: S.state.pose };
479	    });
480	    check(`11 phím p: pose ${pose.p0} → ${pose.p1} trong photoHold (= 4) → ${pose.end} (= 0)`, pose.p0 === 4 && pose.p1 === 4 && pose.end === 0);
481	    await waitCount(2); await frames(Q, 4);
482	    check(`11 phím p: thêm đúng 1 file (tổng ${got.length} = 2), tên hợp lệ`, got.length === 2 && NAME.test(got[1].suggestedFilename()));
483	    // 5 lần bấm trong một khung
484	    const n0 = got.length;
485	    await Q.evaluate(() => { const b = document.getElementById('stPhoto'); for (let i = 0; i < 5; i++) b.click(); });
486	    await waitCount(n0 + 1); await frames(Q, 6);
487	    const many = got.slice(n0), am = [];
488	    for (const d of many) am.push(await analyse(d));
489	    check(`11 bấm 5 lần trong một khung: ${many.length} file (1..5), mỗi file hợp lệ (${am.map((a) => a.colors).join(',')} màu)`, many.length >= 1 && many.length <= 5 && am.every(valid));
490	    // đổi kích thước rồi bấm ngay: kích thước file = canvas lúc chụp
491	    const n1 = got.length;
492	    await Q.setViewportSize({ width: 560, height: 315 });
493	    await Q.evaluate(() => document.getElementById('stPhoto').click());
494	    await waitCount(n1 + 1); await frames(Q, 6);
495	    const ar = await analyse(got[n1]), lr = await Q.evaluate(() => window.__app.stroll.stroll.photoLast);
496	    check(`11 đổi cỡ cửa sổ rồi bấm ngay: file ${ar.w}×${ar.h} = canvas lúc chụp ${lr.w}×${lr.h}, ${got.length - n1} file (= 1)`, got.length === n1 + 1 && valid(ar) && ar.w === lr.w && ar.h === lr.h);
497	    // bậc chất lượng thấp nhất
498	    const n2 = got.length;
499	    await Q.evaluate(() => { const s = document.getElementById('qualitySel'); s.value = 'low'; s.dispatchEvent(new Event('change', { bubbles: true })); });
500	    await frames(Q, 4);
501	    await Q.evaluate(() => document.getElementById('stPhoto').click());
502	    await waitCount(n2 + 1); await frames(Q, 4);
503	    const aq = await analyse(got[n2]);
504	    check(`11 chất lượng thấp: ${got.length - n2} file (= 1), ${aq.w}×${aq.h}, ${aq.colors} màu, hợp lệ`, got.length === n2 + 1 && valid(aq));
505	    check('console sạch (chụp ảnh)', C.errors.length === 0);
506	    if (C.errors.length) console.log(C.errors.join('\n'));
507	    await Q.close();
508	  }
